(()=>{
const entries=[["Tempoyak Ikan Patin", "HIDANGAN SUNGAI", "Ikan patin dengan fermentasi durian, bercita rasa asam, gurih, dan pedas.", "tempoyak-ikan-patin", "Tempoyak ikan patin adalah masakan khas Jambi yang memadukan ikan patin dengan tempoyak, yaitu durian yang difermentasi. Kata “tempoyak” berasal dari “poyak” yang berarti “koyak”, merujuk pada cara durian dipecah menjadi potongan-potongan. Tempoyak dibuat dengan menambahkan garam pada daging durian yang melibatkan bakteri asam laktat, dan sebutan ini paling banyak dipakai pada masyarakat beretnis Melayu.\nDurian yang melimpah saat musim panen cepat matang dan tidak tahan lama. Karena itu durian perlu diolah agar umur simpannya lebih panjang, dan salah satu hasil olahannya adalah tempoyak. Prosesnya diawali dengan memeram daging durian dalam toples tertutup rapat dengan tambahan garam, dan memerlukan waktu sekitar 3–7 hari. Tempoyak yang difermentasi 3–5 hari terasa asam tetapi masih menyisakan manis.\nBakteri yang dominan pada tempoyak adalah bakteri asam laktat dari genus Lactobacillus, antara lain L. plantarum, L. casei, dan L. fermentum. Rasa asam tempoyak berasal dari asam yang dihasilkan bakteri asam laktat selama fermentasi, dan kandungan gula durian yang tinggi mendukung pertumbuhannya.\nIkan patin banyak ditemukan di Sungai Batanghari dan sering menjadi menu utama yang disajikan dengan nasi hangat dan sambal pedas. Gulai tempoyak biasanya diolah dengan patin atau ikan sungai lainnya dalam kuah santan dengan rempah, dan rasanya memadukan asam, gurih, dan pedas. Hidangan ini mencerminkan kedekatan masyarakat Jambi dengan sungai dan kebun. Gulai tempoyak sering disajikan pada acara adat atau makan bersama keluarga besar, sehingga melambangkan kebersamaan.\nYuliana, N. (2007)."], ["Nasi Gemuk", "SARAPAN TRADISIONAL", "Nasi gurih khas Jambi dengan lauk pelengkap dan kerupuk.", "nasi-gemuk", "Nasi gemuk adalah makanan khas Kota Jambi yang mirip dengan nasi uduk khas Betawi atau nasi yang disajikan bersama campuran lauk pelengkap di daerah-daerah lain. Perbedaan antara nasi gemuk dengan nasi uduk terletak pada lauk pendampingnya. Kalau nasi uduk biasanya disajikan bersama emping melinjo, sementara nasi gemuk tidak memakai emping dan justru menggunakan kerupuk.\nDi Provinsi Jambi, nasi gemuk biasanya dihidangkan sebagai menu pembuka hari. Nasi gemuk dibuat dari bahan baku beserta proses pengolahan yang nyaris sama dengan nasi uduk. Cita rasa keduanya pun serupa. Nasi gemuk dikenal sebagai makanan khas Jambi, sedangkan nasi uduk dikenal sebagai makanan khas Jakarta.\nDahmiri, S. E., & Fitriaty, M. D. (2023)."], ["Kue Padamaran", "JAJANAN TRADISIONAL", "Kue hijau bertekstur lembut dengan santan dan kinca gula merah.", "kue-padamaran", "Kue padamaran adalah panganan ringan yang mempunyai nilai tradisional yang terkenal di Jambi. Kue padamaran sendiri adalah kue khas Jambi yang terbuat dari bahan baku tepung beras dan santan. Kue padamaran mempunyai cita rasa yang gurih dengan tekstur lembut menyerupai bubur sumsum. Perbedaan antara kue padamaran dengan bubur sumsum terletak pada penggunaan kinca gula merahnya.\nKalau bubur sumsum kinca gula merahnya disiram pada bagian atas, sedangkan pada kue padamaran kinca gula merah tak hanya digunakan untuk bagian atas kue, tetapi juga bagian dasarnya. Kue padamaran memiliki warna hijau yang merupakan hasil penggunaan air suji."], ["Gulai Tepek Ikan", "HIDANGAN ADAT", "Olahan adonan ikan dan sagu dalam kuah gulai yang asam, gurih, dan segar.", "gulai-tepek-ikan", "Pada pesta pernikahan dengan mengadopsi adat Jambi, biasanya ada kuliner khas Jambi yang tersaji, yakni gulai tepek ikan. Gulai tepek ikan adalah makanan berkuah santan yang menggunakan bahan baku irisan ikan tenggiri, gabus, atau belida yang diolah mirip pempek. Gulai tepek ikan dibuat dari ikan yang dicampur bersama adonan tepung sagu dan bawang putih, kemudian dibentuk seperti pempek lenjer dan dimasak hingga matang. Adonan yang sudah matang berikutnya dicampur ke dalam kuah santan gulai yang rasanya asam gurih.\nKata tepek pada nama makanan ini merujuk pada proses pembuatan adonan ikan yang dipadatkan atau dipipihkan sebelum direbus hingga matang. Tepek ikan yang sudah matang akan disajikan dalam bentuk potongan kecil berbentuk jajar genjang bersama kuahnya yang asam, gurih, dan segar."]];
const photos={"tempoyak-ikan-patin": "data:image/jpeg;base64,", "nasi-gemuk": "data:image/jpeg;base64,", "kue-padamaran": "data:image/jpeg;base64,", "gulai-tepek-ikan": "data:image/jpeg;base64,"};
const grid=document.getElementById('foodGrid'); if(!grid)return;
const dialog=document.createElement('dialog'); dialog.className='culture-detail'; dialog.setAttribute('aria-label','Detail kuliner Jambi'); document.body.append(dialog);
const el=(tag,cls,txt)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(txt)e.textContent=txt;return e;};
function photo(item,cls){const img=el('img',cls);img.src=photos[item[3]];img.alt=item[0];return img;}
function open(item){dialog.replaceChildren();const close=el('button','dialog-close','✕');close.type='button';close.setAttribute('aria-label','Tutup');close.onclick=()=>dialog.close();dialog.append(close,el('h3','',item[0]),photo(item,'culture-detail-photo'));for(const line of item[4].split('\n')){dialog.append(el('p','',line));}dialog.showModal();dialog.scrollTop=0;}
function render(){grid.replaceChildren();for(const item of entries){const card=el('article','culture-card');const foot=el('div','card-foot');const btn=el('button','','Baca Selengkapnya →');btn.type='button';btn.onclick=()=>open(item);foot.append(el('span','','Kuliner Jambi'),btn);card.append(photo(item,'culture-photo'+(item[3]==='batik-angso-duo'?' batik':'')),el('span','card-label',item[1]),el('h3','culture-title',item[0]),el('p','',item[2]),foot);grid.append(card);}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',render);else render();})();